use super::{layout, render_import_block, split_head, ImportSpec};

/// Splice the module's rendered import block into its canonical slot: after the module doc-comment
/// (if any), above the body, separated by exactly one blank on each side. Empty imports ⇒ the code is
/// returned untouched, so a record with no `imports` field materializes byte-for-byte as stored.
pub fn body_with_imports(code: &str, imports: &[ImportSpec]) -> String {
    if imports.is_empty() {
        return code.to_string();
    }
    let (head, body) = split_head(code);
    layout(head, &render_import_block(imports), body)
}
